import{_ as n,o as s,c as a,a4 as t}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse(`{"title":"ADR-0030 — Conservation des données : une décision de l'organisation, l'anonymisation plutôt que la destruction","description":"Extrait de docs/adr/0030-conservation-des-donnees-anonymisation.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0030 — Conservation des données : une décision de l'organisation, l'anonymisation plutôt que la destruction","description":"Extrait de docs/adr/0030-conservation-des-donnees-anonymisation.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0030-conservation-des-donnees-anonymisation.md","filePath":"developpeurs/adr/0030-conservation-des-donnees-anonymisation.md"}`),i={name:"developpeurs/adr/0030-conservation-des-donnees-anonymisation.md"};function r(o,e,d,u,l,c){return s(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0030--conservation-des-données--une-décision-de-lorganisation-lanonymisation-plutôt-que-la-destruction" tabindex="-1">ADR-0030 — Conservation des données : une décision de l&#39;organisation, l&#39;anonymisation plutôt que la destruction <a class="header-anchor" href="#adr-0030--conservation-des-données--une-décision-de-lorganisation-lanonymisation-plutôt-que-la-destruction" aria-label="Permalink to &quot;ADR-0030 — Conservation des données : une décision de l&#39;organisation, l&#39;anonymisation plutôt que la destruction {#adr-0030--conservation-des-données--une-décision-de-lorganisation-lanonymisation-plutôt-que-la-destruction}&quot;">​</a></h1><p><strong>Date :</strong> 17 septembre 2026 <strong>Statut :</strong> Accepté avec garde-fou <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> audit de sécurité et RGPD du 15 septembre 2026 (constats 8.2 et 11.1) ; RGPD art. 5-1-c (minimisation) et 5-1-e (limitation de la conservation) ; Code du patrimoine, art. L212-2 et L212-3 (destruction des archives publiques) ; CDC_CMS_AI_Native_v1.1 §13.1 ; prolonge l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0017-fichiers-personnels-adresses-par-identifiant">ADR-0017</a> et la doctrine de <code>technical_audit_retention_days</code> posée à l&#39;Epic E5</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>L&#39;audit du 15 septembre a relevé deux défauts de même famille.</p><p><strong>Une copie de trop.</strong> Le contexte de toute notification liée à une demande contenait <code>all_fields</code> — chaque champ renseigné, libellé et valeur — et le moteur d&#39;envoi l&#39;écrivait tel quel dans <code>notification_deliveries.context</code>. Pour une demande d&#39;aide sociale, une inscription scolaire ou une candidature, le journal d&#39;envoi était devenu une <strong>seconde base de données personnelles</strong>, créée pour tracer une délivrance, qui n&#39;avait besoin ni de ces valeurs ni de les garder. Aucune route ne l&#39;exposait : la copie n&#39;avait même pas l&#39;utilité qui l&#39;aurait justifiée.</p><p><strong>Rien n&#39;était jamais effacé.</strong> Ni les demandes d&#39;usagers — soumissions confirmées, enregistrements générés, fils de discussion —, ni le journal d&#39;envoi, ni les preuves de consentement échues, ni les adresses des personnes entièrement désabonnées, ni les sessions expirées. Plus structurant : <strong>la durée de conservation d&#39;une demande n&#39;était paramétrable nulle part.</strong> Le code le reconnaissait lui-même (<code>app/api/account.py</code>) — « une saisine instruite par un service a sa propre durée de conservation » — sans que cette durée existe.</p><p>Deux contraintes rendent la réponse moins évidente qu&#39;une purge planifiée.</p><p><strong>Pour une collectivité, une saisine est une archive publique.</strong> Le Code du patrimoine soumet la destruction des archives publiques au visa de l&#39;administration des archives. Un CMS qui supprimerait seul une demande arrivée à échéance ferait accomplir à l&#39;organisme un acte qu&#39;il n&#39;a pas le droit d&#39;accomplir sans ce visa.</p><p><strong>La durée n&#39;appartient pas au logiciel.</strong> Le RGPD la confie au responsable de traitement ; pour un organisme public, elle se fixe avec le service d&#39;archives, à partir de la durée d&#39;utilité administrative de chaque type de dossier. L&#39;auteur d&#39;un plugin ne la connaît pas, et le Core encore moins.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>Le CMS minimise ce qu&#39;il copie, ne conserve que ce que l&#39;organisation a décidé de conserver, et anonymise à échéance au lieu de détruire.</strong></p><h3 id="1-aucune-valeur-saisie-dans-le-journal-denvoi" tabindex="-1">1. Aucune valeur saisie dans le journal d&#39;envoi <a class="header-anchor" href="#1-aucune-valeur-saisie-dans-le-journal-denvoi" aria-label="Permalink to &quot;1. Aucune valeur saisie dans le journal d&#39;envoi {#1-aucune-valeur-saisie-dans-le-journal-denvoi}&quot;">​</a></h3><p><code>all_fields</code> n&#39;est plus persisté. Il devient une clé <strong>recomposable</strong> : reconstruite depuis l&#39;enregistrement au moment de l&#39;envoi, avec la fonction qui la produisait déjà. Les deux mécanismes existants ne convenaient pas, et c&#39;est ce qui a imposé le troisième : le contexte persisté aurait gardé la copie ; <code>secret_context</code>, qui n&#39;est jamais journalisé, rend un message <strong>non rejouable</strong> — ranger le récapitulatif là aurait rendu tous les accusés de réception irrécupérables sur une panne du relais de messagerie. Un accusé de réception en échec reste donc rejoué, avec son récapitulatif ; un ré-essai sur une demande supprimée ou anonymisée échoue définitivement.</p><h3 id="2-aucune-purge-tant-que-lorganisation-na-pas-décidé" tabindex="-1">2. Aucune purge tant que l&#39;organisation n&#39;a pas décidé <a class="header-anchor" href="#2-aucune-purge-tant-que-lorganisation-na-pas-décidé" aria-label="Permalink to &quot;2. Aucune purge tant que l&#39;organisation n&#39;a pas décidé {#2-aucune-purge-tant-que-lorganisation-na-pas-décidé}&quot;">​</a></h3><p>C&#39;est la doctrine que l&#39;Epic E5 avait posée pour le journal technique, et elle s&#39;étend ici à tout ce qui porte une valeur administrative ou probatoire : <strong>l&#39;absence de décision se lit comme une absence de purge, pas comme une purge par défaut.</strong> Trois durées rejoignent la politique RGPD de l&#39;organisation, toutes « non décidé » par défaut :</p><ul><li><strong>la durée de chaque type de demande</strong>, fixée <strong>par type de contenu</strong> — parce qu&#39;une candidature et une saisine d&#39;urbanisme n&#39;ont pas la même durée d&#39;utilité administrative ;</li><li>la durée du journal d&#39;envoi ;</li><li>la durée de conservation des preuves de consentement et des adresses des personnes entièrement désabonnées.</li></ul><p>La durée d&#39;une demande vit dans la politique de l&#39;<strong>organisation</strong>, pas dans la configuration de formulaire qu&#39;un <strong>plugin</strong> déclare : c&#39;est une décision du responsable de traitement, pas de l&#39;auteur du module.</p><p>Seule exception : <strong>les sessions expirées ou révoquées</strong> sont purgées après 30 jours, par une constante. Ce n&#39;est pas une décision de responsable de traitement mais de l&#39;hygiène technique, et l&#39;historique des connexions est déjà tenu, avec sa propre durée, par le journal d&#39;accès aux données personnelles.</p><h3 id="3-à-échéance-on-anonymise" tabindex="-1">3. À échéance, on anonymise <a class="header-anchor" href="#3-à-échéance-on-anonymise" aria-label="Permalink to &quot;3. À échéance, on anonymise {#3-à-échéance-on-anonymise}&quot;">​</a></h3><p>Une demande échue garde sa référence, son type, ses dates et son état ; tous les champs marqués « données personnelles » sont vidés — jusque dans les répéteurs et les groupes —, ses messages et son journal d&#39;envoi sont supprimés, son jeton de suivi est effacé. La trace administrative et les statistiques survivent ; les personnes disparaissent. L&#39;enregistrement porte l&#39;horodatage de l&#39;opération, qui la rend idempotente et visible, et qu&#39;aucun agent ne peut poser ni effacer.</p><p><strong>Le point de départ est la date de dépôt</strong>, pas une date de clôture : le Core n&#39;a pas de notion générique de clôture d&#39;une demande. Une organisation qui raisonne en « N ans après la clôture » doit donc ajouter à sa durée le délai habituel d&#39;instruction.</p><p><strong>Le garde-fou</strong> — ce qui fait passer cette ADR de « Accepté » à « Accepté avec garde-fou ». Anonymiser suppose de savoir quoi vider. Un type de contenu déclaré porteur de données personnelles <strong>sans qu&#39;aucun de ses champs le soit</strong> ne dit pas où elles se trouvent : l&#39;anonymisation y est <strong>refusée</strong>, jamais tentée « au mieux », et la politique refuse qu&#39;on lui pose une durée. Le registre des traitements le signale, comme il signale tout formulaire public sans durée décidée — l&#39;absence de décision devient un écart visible au lieu d&#39;un choix fait à la place du DPO et de l&#39;archiviste.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Supprimer à échéance</strong></td><td>Plus simple et plus certain au regard du RGPD. Mais pour un organisme public, c&#39;est une destruction d&#39;archive que le CMS accomplirait seul, sans le visa que le Code du patrimoine exige.</td></tr><tr><td><strong>Une durée par défaut</strong> (par exemple deux ans)</td><td>Les données partiraient sans que personne y pense — et le logiciel trancherait seul une durée que la loi confie au responsable de traitement, en détruisant peut-être des archives au passage.</td></tr><tr><td><strong>La durée dans le <code>FormConfig</code> du plugin</strong></td><td>L&#39;auteur d&#39;un plugin ne connaît pas la durée d&#39;utilité administrative d&#39;une collectivité ; deux organisations qui installent le même plugin n&#39;ont pas la même.</td></tr><tr><td><strong><code>all_fields</code> dans <code>secret_context</code></strong></td><td>Le récapitulatif ne serait plus journalisé — mais aucun accusé de réception ne serait plus rejouable après une panne du relais, régression plus grave que le défaut corrigé.</td></tr><tr><td><strong>Anonymiser « au mieux »</strong> un type sans champ marqué (vider tout le texte libre, par exemple)</td><td>Une anonymisation dont on ne peut pas dire ce qu&#39;elle a laissé n&#39;en est pas une ; la présenter comme faite serait pire que de ne rien faire.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Le journal d&#39;envoi cesse d&#39;être une copie des demandes.</li><li>Une organisation peut enfin décider de la durée de conservation de chaque type de demande, et voit dans le registre celles qu&#39;elle n&#39;a pas encore décidées.</li><li>Les statistiques d&#39;activité survivent à l&#39;échéance ; les archives publiques ne sont pas détruites par le logiciel.</li></ul><p><strong>Négatives, et il y en a</strong></p><ul><li><strong>Une installation qui ne décide rien ne purge rien.</strong> C&#39;est voulu, mais c&#39;est un risque réel : le registre rend l&#39;écart visible, il ne le comble pas.</li><li><strong>L&#39;anonymisation vaut ce que vaut le marquage des champs.</strong> Un champ de texte libre non marqué qui contiendrait un nom resterait. Le garde-fou arrête le cas grossier (aucun champ marqué) ; il ne vérifie pas que chaque champ l&#39;est à juste titre.</li><li><strong>Le point de départ est la date de dépôt</strong>, pas la clôture — à intégrer par l&#39;organisation dans la durée qu&#39;elle déclare.</li><li>Le sort final <strong>« supprimer »</strong> n&#39;est pas proposé. Un organisme privé, que le Code du patrimoine ne concerne pas, pourrait le préférer ; la question se rouvrira s&#39;il se présente.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Compléter l&#39;export RGPD d&#39;un compte usager avec les données de ses demandes (constat 9.1 de l&#39;audit). → <strong>Close</strong> le 17/09/2026 (commit <code>629fdfa</code>) : l&#39;export du compte contient ses demandes, leurs messages et leurs fichiers.</li><li>[x] Ouvrir un droit d&#39;accès et d&#39;effacement au déposant sans compte (constat 9.2). → <strong>Close</strong> par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0032-droits-du-deposant-sans-compte">ADR-0032</a> (17/09/2026).</li><li>[ ] Rouvrir le sort final « supprimer » si un organisme privé le demande.</li></ul>',31)])])}const g=n(i,[["render",r]]);export{m as __pageData,g as default};
